_WHISPER_MODEL_CACHE: Any = None
_DIALOG_GUARD_JS_CACHE: str | None = None

_JS_DIALOG_DESTRUCTIVE_RE = re.compile(
    r"\b("
    r"delete|remove|withdraw|discard|"
    r"cancel\s+(?:your\s+|this\s+)?application|"
    r"clear\s+(?:all|form|answers)|"
    r"reset\s+form|unsubscribe|revoke|deactivate|close\s+account|"
    r"leave\s+without\s+saving"
    r")\b",
    re.IGNORECASE,
)

_JS_DIALOG_SUBMIT_FINALITY_RE = re.compile(
    r"\b("
    r"ready\s+to\s+submit|"
    r"cannot\s+be\s+changed\s+once\s+submitted|"
    r"answers\s+cannot\s+be\s+changed|"
    r"once\s+submitted|"
    r"submit\s+(?:your\s+|this\s+|the\s+)?(?:application|form|answers|response)|"
    r"confirm\s+submission|"
    r"finalize\s+(?:your\s+)?(?:application|submission)|"
    r"want\s+to\s+submit|"
    r"proceed\s+with\s+submission"
    r")\b",
    re.IGNORECASE,
)

_JS_DIALOG_PROMPT_TOKEN_RE = re.compile(
    r"""(?:type|enter|write|input)\s+["'`]([A-Za-z0-9 _-]{2,24})["'`]""",
    re.IGNORECASE,
)


def _decide_js_dialog_action(
    dialog_type: str,
    message: str,
    *,
    allow_submit: bool = True,
    default_prompt: str = "",
    has_unanswered_required: bool = False,
) -> tuple[bool, str | None]:
    """Deterministically resolve browser native JS dialogs (`alert`, `confirm`, `prompt`, `beforeunload`)."""
    dtype = str(dialog_type or "alert").strip().lower()
    msg = str(message or "").strip()
    is_submit_finality = bool(_JS_DIALOG_SUBMIT_FINALITY_RE.search(msg))
    is_destructive = bool(_JS_DIALOG_DESTRUCTIVE_RE.search(msg)) and not is_submit_finality

    if dtype in ("alert", "beforeunload"):
        return True, None

    if dtype == "confirm":
        if is_destructive:
            return False, None
        if is_submit_finality and (not allow_submit or has_unanswered_required):
            return False, None
        return True, None

    if dtype == "prompt":
        if is_destructive:
            return False, None
        if is_submit_finality and (not allow_submit or has_unanswered_required):
            return False, None
        token_match = _JS_DIALOG_PROMPT_TOKEN_RE.search(msg)
        if token_match:
            return True, token_match.group(1).strip()
        return True, str(default_prompt or "")

    return True, None


def _load_companion_dialog_guard_js() -> str:
    """Load `dialog_guard_main.js` for CDP `Page.addScriptToEvaluateOnNewDocument` and runtime injection."""
    global _DIALOG_GUARD_JS_CACHE
    if _DIALOG_GUARD_JS_CACHE:
        return _DIALOG_GUARD_JS_CACHE

    candidates: list[Path] = [
        Path(__file__).resolve().parents[2] / "packaging" / "extensions" / "autoapply_companion" / "dialog_guard_main.js",
    ]
    for parent in Path(__file__).resolve().parents:
        candidates.append(parent / "extensions" / "autoapply_companion" / "dialog_guard_main.js")
        candidates.append(parent / "Resources" / "extensions" / "autoapply_companion" / "dialog_guard_main.js")
    app_sup = os.environ.get("AUTOAPPLY_APP_SUPPORT", "").strip()
    if app_sup:
        candidates.append(Path(app_sup).expanduser() / "extensions" / "autoapply_companion" / "dialog_guard_main.js")
    candidates.append(
        Path.home() / "Library" / "Application Support" / "AutoApply" / "extensions" / "autoapply_companion" / "dialog_guard_main.js"
    )

    for cand in candidates:
        try:
            if cand.is_file():
                txt = cand.read_text(encoding="utf-8")
                if txt.strip():
                    _DIALOG_GUARD_JS_CACHE = txt
                    return txt
        except Exception:
            continue
    return ""


async def _cdp_enable_dialog_guard_on_ws(
    send_fn: Any,
    *,
    mode: str = "apply",
    duration_ms: int = 90000,
) -> None:
    """Enable `Page` domain events and arm `dialog_guard_main.js` on an active CDP target WebSocket."""
    try:
        await send_fn("Page.enable", {})
    except Exception:
        pass
    guard_js = _load_companion_dialog_guard_js()
    if not guard_js:
        return
    arm_snippet = (
        f"{guard_js}\n"
        f";try{{if(typeof window.__aaArmDialogGuard==='function')"
        f"window.__aaArmDialogGuard({json.dumps(mode)}, {int(duration_ms)});}}catch(_){{}}"
    )
    try:
        await send_fn("Page.addScriptToEvaluateOnNewDocument", {"source": arm_snippet})
    except Exception:
        pass
    try:
        await send_fn("Runtime.evaluate", {"expression": arm_snippet, "returnByValue": True})
    except Exception:
        pass


async def _cdp_drain_post_action_dialogs(
    ws: Any,
    *,
    allow_submit: bool = True,
    duration_sec: float = 0.85,
) -> int:
    """Drain and resolve any asynchronous `Page.javascriptDialogOpening` events triggered shortly after a click/submit."""
    handled = 0
    loop = asyncio.get_running_loop()
    deadline = loop.time() + max(0.05, duration_sec)
    msg_seq = 90000
    while True:
        rem = deadline - loop.time()
        if rem <= 0:
            break
        try:
            raw = await asyncio.wait_for(ws.recv(), timeout=min(0.22, rem))
            ev = json.loads(raw)
        except Exception:
            break
        if ev.get("method") == "Page.javascriptDialogOpening":
            params = ev.get("params") or {}
            accept_flag, prompt_txt = _decide_js_dialog_action(
                str(params.get("type") or "alert"),
                str(params.get("message") or ""),
                allow_submit=allow_submit,
                default_prompt=str(params.get("defaultPrompt") or ""),
            )
            handle_params: dict[str, Any] = {"accept": accept_flag}
            if prompt_txt is not None:
                handle_params["promptText"] = prompt_txt
            msg_seq += 1
            try:
                await ws.send(
                    json.dumps(
                        {
                            "id": msg_seq,
                            "method": "Page.handleJavaScriptDialog",
                            "params": handle_params,
                        }
                    )
                )
                handled += 1
            except Exception:
                break
    return handled


async def _cdp_probe_or_recover_target_async(port: int, target: dict[str, Any]) -> str:
    """Verify a CDP target is responsive; if frozen by a pre-existing native modal dialog, self-heal via browser-root Target replacement."""
    import websockets

    ws_url = str(target.get("webSocketDebuggerUrl") or "").strip()
    if not ws_url:
        return ""
    t_type = str(target.get("type") or "page")
    t_url = str(target.get("url") or "").strip()
    t_id = str(target.get("id") or "").strip()

    responsive = False
    try:
        async with websockets.connect(ws_url, open_timeout=1.1, close_timeout=0.5) as ws:
            await ws.send(json.dumps({"id": 1, "method": "Page.enable", "params": {}}))
            await ws.send(
                json.dumps(
                    {
                        "id": 2,
                        "method": "Page.handleJavaScriptDialog",
                        "params": {"accept": False},
                    }
                )
            )
            await ws.send(
                json.dumps(
                    {
                        "id": 3,
                        "method": "Runtime.evaluate",
                        "params": {"expression": "1", "returnByValue": True},
                    }
                )
            )
            loop = asyncio.get_running_loop()
            deadline = loop.time() + 1.15
            while loop.time() < deadline:
                rem = max(0.05, deadline - loop.time())
                raw = json.loads(await asyncio.wait_for(ws.recv(), timeout=rem))
                if raw.get("method") == "Page.javascriptDialogOpening":
                    await ws.send(
                        json.dumps(
                            {
                                "id": 4,
                                "method": "Page.handleJavaScriptDialog",
                                "params": {"accept": False},
                            }
                        )
                    )
                elif raw.get("id") == 3:
                    responsive = True
                    break
    except Exception:
        responsive = False

    if responsive:
        return ws_url

    if t_type != "page" or not t_id or not t_url.startswith(("http://", "https://")):
        return ws_url

    # Target renderer is blocked by a pre-existing native modal dialog.
    # Recover cleanly via the always-responsive browser-root WebSocket without clicking OK on an incomplete form.
    try:
        with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/version", timeout=0.8) as vr:
            ver_info = json.loads(vr.read().decode("utf-8", errors="ignore"))
        browser_ws = str(ver_info.get("webSocketDebuggerUrl") or "").strip()
        if not browser_ws:
            return ws_url

        new_target_id = ""
        async with websockets.connect(browser_ws, open_timeout=1.2, close_timeout=0.6) as bws:
            await bws.send(
                json.dumps(
                    {
                        "id": 1,
                        "method": "Target.createTarget",
                        "params": {"url": t_url},
                    }
                )
            )
            while True:
                msg = json.loads(await asyncio.wait_for(bws.recv(), timeout=2.0))
                if msg.get("id") == 1:
                    new_target_id = str((msg.get("result") or {}).get("targetId") or "")
                    break
            if new_target_id and new_target_id != t_id:
                await bws.send(
                    json.dumps(
                        {
                            "id": 2,
                            "method": "Target.closeTarget",
                            "params": {"targetId": t_id},
                        }
                    )
                )
                try:
                    await asyncio.wait_for(bws.recv(), timeout=1.0)
                except Exception:
                    pass

        if not new_target_id:
            return ws_url

        new_ws_url = ""
        for _ in range(18):
            await asyncio.sleep(0.2)
            try:
                with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/list", timeout=0.6) as lr:
                    cur_tabs = json.loads(lr.read().decode("utf-8", errors="ignore"))
                for ct in cur_tabs:
                    if str(ct.get("id") or "") == new_target_id and ct.get("webSocketDebuggerUrl"):
                        new_ws_url = str(ct["webSocketDebuggerUrl"])
                        break
                if new_ws_url:
                    break
            except Exception:
                continue

        if new_ws_url:
            try:
                async with websockets.connect(new_ws_url, open_timeout=1.2, close_timeout=0.6) as nws:
                    req_id = 1

                    async def _nsend(m: str, p: dict[str, Any] | None = None) -> dict[str, Any]:
                        nonlocal req_id
                        cid = req_id
                        req_id += 1
                        await nws.send(json.dumps({"id": cid, "method": m, "params": p or {}}))
                        while True:
                            rm = json.loads(await asyncio.wait_for(nws.recv(), timeout=2.0))
                            if rm.get("id") == cid:
                                return rm

                    await _cdp_enable_dialog_guard_on_ws(_nsend, mode="prefill", duration_ms=30000)
                    for _ in range(12):
                        rs = await _nsend(
                            "Runtime.evaluate",
                            {"expression": "document.readyState", "returnByValue": True},
                        )
                        state_str = str(rs.get("result", {}).get("result", {}).get("value") or "")
                        if state_str in ("interactive", "complete"):
                            break
                        await asyncio.sleep(0.2)
            except Exception:
                pass
            return new_ws_url
    except Exception:
        pass

    return ws_url


def _hot_reload_live_companion_extension(port: int = 19225) -> bool:
    """Hot-reload the AutoApply Companion MV3 extension inside a running AutoApply Browser instance via CDP."""
    async def _reload() -> bool:
        import websockets

        try:
            with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/list", timeout=0.6) as r:
                targets = json.loads(r.read().decode("utf-8", errors="ignore"))
        except Exception:
            return False

        ext_ws = ""
        temp_target_id = ""
        browser_ws = ""
        for t in targets:
            t_url = str(t.get("url") or "")
            if (
                AUTOAPPLY_COMPANION_EXTENSION_ID in t_url or "autoapply_companion" in t_url
            ) and t.get("webSocketDebuggerUrl"):
                ext_ws = str(t["webSocketDebuggerUrl"])
                break

        if not ext_ws:
            try:
                with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/version", timeout=0.6) as vr:
                    browser_ws = str(
                        json.loads(vr.read().decode("utf-8", errors="ignore")).get("webSocketDebuggerUrl") or ""
                    )
                if browser_ws:
                    async with websockets.connect(browser_ws, open_timeout=1.0, close_timeout=0.5) as bws:
                        await bws.send(
                            json.dumps(
                                {
                                    "id": 1,
                                    "method": "Target.createTarget",
                                    "params": {
                                        "url": f"chrome-extension://{AUTOAPPLY_COMPANION_EXTENSION_ID}/popup.html",
                                    },
                                }
                            )
                        )
                        msg = json.loads(await asyncio.wait_for(bws.recv(), timeout=1.5))
                        temp_target_id = str((msg.get("result") or {}).get("targetId") or "")
                    await asyncio.sleep(0.25)
                    with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/list", timeout=0.6) as r2:
                        for t in json.loads(r2.read().decode("utf-8", errors="ignore")):
                            t_url = str(t.get("url") or "")
                            if AUTOAPPLY_COMPANION_EXTENSION_ID in t_url and t.get("webSocketDebuggerUrl"):
                                ext_ws = str(t["webSocketDebuggerUrl"])
                                break
            except Exception:
                pass

        if not ext_ws:
            return False

        reloaded = False
        try:
            async with websockets.connect(ext_ws, open_timeout=1.0, close_timeout=0.5) as ws:
                await ws.send(
                    json.dumps(
                        {
                            "id": 1,
                            "method": "Runtime.evaluate",
                            "params": {
                                "expression": "chrome.runtime.reload(); true;",
                                "returnByValue": True,
                            },
                        }
                    )
                )
                reloaded = True
                try:
                    await asyncio.wait_for(ws.recv(), timeout=0.4)
                except Exception:
                    pass
        except Exception:
            pass

        if temp_target_id and browser_ws:
            try:
                async with websockets.connect(browser_ws, open_timeout=0.8, close_timeout=0.4) as bws:
                    await bws.send(
                        json.dumps(
                            {
                                "id": 2,
                                "method": "Target.closeTarget",
                                "params": {"targetId": temp_target_id},
                            }
                        )
                    )
            except Exception:
                pass

        return reloaded

    try:
        return asyncio.run(_reload())
    except Exception:
        return False


