class PersistentLocalKeychainCustody:
    """Persists the installation's age private key in a restricted custody folder outside `secrets/`."""

    def __init__(self, custody_dir: Path) -> None:
        self._dir = custody_dir.resolve()
        self._dir.mkdir(parents=True, exist_ok=True, mode=0o700)

    def _path(self, installation_id: str) -> Path:
        safe = re.sub(r"[^a-zA-Z0-9_.-]", "_", installation_id)
        return self._dir / f"{safe}.custody"

    def store_private_key(self, installation_id: str, private_key_material: bytes) -> None:
        p = self._path(installation_id)
        if not p.exists():
            p.write_bytes(bytes(private_key_material))
            try:
                p.chmod(0o600)
            except OSError:
                pass

    def load_private_key(self, installation_id: str) -> bytes | None:
        p = self._path(installation_id)
        if p.is_file():
            return p.read_bytes()
        return None


