class AppWorkspaceManager:
    """Manages persistent SQLite stores, isolated Browser profiles, Knowledge Base Markdown, and JSON state."""

    def __init__(self, app_support_dir: Path) -> None:
        self.root = app_support_dir.resolve()
        self.app_support_dir = self.root
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.state_file = self.root / "workspace_state.json"
        self.kb_dir = self.root / "knowledge_base"
        self.kb_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.profile_dir = self.root / "profile"
        self.profile_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.audio_staging_dir = self.root / "audio-staging"
        self.audio_staging_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.generated_docs_dir = self.root / "artifacts"
        self.generated_docs_dir.mkdir(parents=True, exist_ok=True, mode=0o700)

        self.candidate_store = CandidateStore(db_path=self.root / "candidate.sqlite3")
        self.entitlement_service = EntitlementService(
            db_path=self.root / "entitlements.sqlite3",
            signing_secret="autoapply-local-lease-signing-key-v1",
        )
        self.state_machine = ApplicationStateMachine(db_path=self.root / "applications.sqlite3")
        self.sync_outbox = DurableSyncOutbox(self.root / "sync_outbox.sqlite3")
        self.no_send_register = NoSendRegister(self.root / "no_send.sqlite3")
        self.mail_policy = MailPolicyEngine(no_send_register=self.no_send_register)
        self.resume_importer = ResumeImporter(
            storage_dir=self.root / "resumes",
            candidate_store=self.candidate_store,
        )
        self.renderer = DeterministicDocumentRenderer(output_dir=self.generated_docs_dir)
        self.keychain = PersistentLocalKeychainCustody(self.root / "keychain-custody")
        self.secret_store = SecretEnvelopeBroker(
            installation_id="macos-primary-install",
            secrets_dir=self.root / "secrets",
            keychain=self.keychain,
        )
        self._ensure_secret_store()
        self._ensure_initialized()

    def _ensure_secret_store(self) -> None:
        existing_key = self.keychain.load_private_key("macos-primary-install")
        if existing_key is None or not self.secret_store.envelope_path.exists():
            self.secret_store.initialize_installation_key()

    def _ensure_initialized(self) -> None:
        if self.state_file.exists():
            raw = self._load_raw_state()
            changed = self._upgrade_state_schema(raw)
            if changed:
                self._save_raw_state(raw)
            return

        self.entitlement_service.issue_license_key(
            license_key="AA-LIVE-20USD-0001",
            price_usd_monthly=20,
            server_now=datetime.now(timezone.utc),
        )

        kb_sections = []
