    def _upgrade_state_schema(self, raw: dict[str, Any]) -> bool:
        changed = False
        now_iso = datetime.now(timezone.utc).isoformat()
        if "knowledge_base" not in raw:
            kb_sections = []
            for sec in DEFAULT_KNOWLEDGE_BASE_SECTIONS:
                md_path = self.kb_dir / f"{sec['id']}.md"
                if not md_path.exists():
                    md_path.write_text(sec["markdown"], encoding="utf-8")
                kb_sections.append(
                    {
                        "id": sec["id"],
                        "title": sec["title"],
                        "icon": sec["icon"],
                        "subtitle": sec["subtitle"],
                        "markdown": md_path.read_text(encoding="utf-8"),
                        "is_custom": False,
                        "updated_at": now_iso,
                    }
                )
            raw["knowledge_base"] = {
                "profile_header": {
                    "full_name": "",
                    "pronouns": "",
                    "headline": "",
                    "email": "",
                    "phone": "",
                    "location": "",
                    "linkedin_url": "",
                    "github_url": "",
                    "portfolio_url": "",
                    "photo_path": "",
                    "include_photo_on_resume": False,
                },
                "sections": kb_sections,
            }
            changed = True
        else:
            hdr_dict = raw["knowledge_base"].setdefault("profile_header", {})
            if "pronouns" not in hdr_dict:
                hdr_dict["pronouns"] = ""
                changed = True
            for existing_sec in raw["knowledge_base"].get("sections", []):
                md_path = self.kb_dir / f"{existing_sec.get('id', '')}.md"
                if md_path.is_file():
                    disk_md = md_path.read_text(encoding="utf-8")
                    if existing_sec.get("markdown") != disk_md:
                        existing_sec["markdown"] = disk_md
                        changed = True
            existing_ids = {s["id"] for s in raw["knowledge_base"].get("sections", [])}
            for sec in DEFAULT_KNOWLEDGE_BASE_SECTIONS:
                if sec["id"] not in existing_ids:
                    md_path = self.kb_dir / f"{sec['id']}.md"
                    if not md_path.exists():
                        md_path.write_text(sec["markdown"], encoding="utf-8")
                    raw["knowledge_base"].setdefault("sections", []).append(
                        {
                            "id": sec["id"],
                            "title": sec["title"],
                            "icon": sec["icon"],
                            "subtitle": sec["subtitle"],
                            "markdown": md_path.read_text(encoding="utf-8"),
                            "is_custom": False,
                            "updated_at": now_iso,
                        }
                    )
                    changed = True

        onb_dict = raw.setdefault("onboarding", {})
        if "chatgpt_config" not in onb_dict:
            onb_dict["chatgpt_config"] = {
                "connected": False,
                "optional": True,
                "account_email": "",
                "auth_method": "codex_device_auth",
                "status_label": "Optional — Uses OpenRouter (Dolphin 3) if not connected",
                "logic_provider": "openrouter_default",
                "pending_user_code": "",
                "verification_url": "https://auth.openai.com/codex/device",
            }
            changed = True
        else:
            cg_d = onb_dict["chatgpt_config"]
            if "optional" not in cg_d:
                cg_d["optional"] = True
                changed = True
            if "pending_user_code" not in cg_d:
                cg_d["pending_user_code"] = ""
                changed = True
            if "verification_url" not in cg_d:
                cg_d["verification_url"] = "https://auth.openai.com/codex/device"
                changed = True
            if cg_d.get("connected") and "Optional" in str(cg_d.get("status_label", "")):
                cg_d["status_label"] = "Connected — OpenAI Codex Subscription Active"
                cg_d["logic_provider"] = "chatgpt_subscription"
                changed = True

        ai_cfg_init = onb_dict.setdefault("ai_config", {})
        cur_logic_init = str(ai_cfg_init.get("logic_model", "")).strip()
        if (
            not cur_logic_init
            or cur_logic_init == "cognitivecomputations/dolphin-mistral-24b-venice-edition"
            or cur_logic_init == "openai/codex-commercial-session"
        ):
            ai_cfg_init["logic_model"] = (
                "openai-codex/gpt-6.1-sol"
                if (onb_dict.get("chatgpt_config", {}).get("connected") or cur_logic_init == "openai/codex-commercial-session")
                else "~deepseek/deepseek-flash-latest"
            )
            if ai_cfg_init.get("orchestrator_fallback_model") == "openai/codex-commercial-session":
                ai_cfg_init["orchestrator_fallback_model"] = ai_cfg_init["logic_model"]
