    @staticmethod
    def _generate_site_password(length: int = 20, max_length_hint: int | None = None) -> str:
        """Generate a strong random password with uppercase, lowercase, digits, and special characters.
        Default length is 20 chars; automatically adjusts to 12 chars if length <= 12 or max_length_hint < 20.
        """
        import secrets
        import string

        target_len = 20
        if length <= 12 or (max_length_hint is not None and 8 <= max_length_hint < 20):
            target_len = 12
        elif length > 0:
            target_len = length

        upper = string.ascii_uppercase
        lower = string.ascii_lowercase
        digits = string.digits
        specials = "!@#$%^&*()-_=+"
        all_chars = upper + lower + digits + specials

        min_per_class = 2 if target_len <= 12 else 3
        chars: list[str] = []
        for pool in (upper, lower, digits, specials):
            for _ in range(min_per_class):
                chars.append(secrets.choice(pool))
        while len(chars) < target_len:
            chars.append(secrets.choice(all_chars))
        secrets.SystemRandom().shuffle(chars)
        # Ensure first character is a letter so strict enterprise portals (e.g. Workday/Taleo) never reject leading symbols
        if not chars[0].isalpha():
            for idx, ch in enumerate(chars):
                if ch.isalpha():
                    chars[0], chars[idx] = chars[idx], chars[0]
                    break
        return "".join(chars[:target_len])

    @staticmethod
    def _compute_totp_code(totp_token: str) -> str:
        """Compute live 6-digit RFC 6238 TOTP code if totp_token is a Base32 secret or otpauth:// URI, else return token."""
        raw_tok = (totp_token or "").strip()
        if not raw_tok:
            return ""
        secret_str = raw_tok
        if raw_tok.lower().startswith("otpauth://"):
            try:
                parsed_u = urllib.parse.urlparse(raw_tok)
                qs = urllib.parse.parse_qs(parsed_u.query)
                if "secret" in qs and qs["secret"]:
                    secret_str = qs["secret"][0].strip()
            except Exception:
                pass
        clean_b32 = re.sub(r"[\s\-]", "", secret_str).upper()
        if re.fullmatch(r"[0-9]{6,8}", clean_b32):
            return clean_b32
        if len(clean_b32) >= 8 and re.fullmatch(r"[A-Z2-7]+=*", clean_b32):
            try:
                import hmac
                import struct
                import time

                pad_len = (8 - (len(clean_b32) % 8)) % 8
                key_bytes = base64.b32decode(clean_b32 + ("=" * pad_len), casefold=True)
                counter = int(time.time() // 30)
                msg = struct.pack(">Q", counter)
                digest = hmac.new(key_bytes, msg, hashlib.sha1).digest()
                offset = digest[-1] & 0x0F
                code_int = (struct.unpack(">I", digest[offset : offset + 4])[0] & 0x7FFFFFFF) % 1000000
                return f"{code_int:06d}"
            except Exception:
                return raw_tok
        return raw_tok

    def _enrich_password_vault_entries(self, vault: list[dict[str, Any]]) -> list[dict[str, Any]]:
        enriched: list[dict[str, Any]] = []
        for item in vault:
            if not isinstance(item, dict):
                continue
            entry = dict(item)
            pwd = str(entry.get("password") or "")
            entry["password_length"] = int(entry.get("password_length") or len(pwd) or 20)
            totp_raw = str(entry.get("totp_token") or "").strip()
            entry["totp_token"] = totp_raw
            entry["totp_current_code"] = self._compute_totp_code(totp_raw) if totp_raw else ""
            entry["auto_registered"] = bool(entry.get("auto_registered", False))
            enriched.append(entry)
        return enriched

    def _upsert_password_vault_entry(
        self,
        *,
        raw: dict[str, Any],
        entry_id: str = "",
        website_name: str,
        website_url: str,
        username: str,
        password: str = "",
        totp_token: str = "",
        description: str = "",
        auto_registered: bool = False,
        adjust_to_12_chars: bool = False,
        max_length_hint: int | None = None,
        now: datetime | None = None,
    ) -> dict[str, Any]:
        now_dt = now or datetime.now(timezone.utc)
        ts_str = now_dt.strftime("%Y-%m-%d %H:%M")
        vault = raw.setdefault("password_vault", [])
        if not isinstance(vault, list):
            vault = []
            raw["password_vault"] = vault

        clean_url = website_url.strip()
        clean_name = website_name.strip()

        def _extract_norm_host(u_str: str) -> str:
            s = str(u_str or "").strip()
            if not s:
                return ""
            try:
                parsed = urllib.parse.urlparse(s if "://" in s else f"https://{s}")
                h = (parsed.netloc or parsed.path.split("/")[0] or "").lower().strip()
                if ":" in h:
                    h = h.split(":", 1)[0]
                if h.startswith("www."):
                    h = h[4:]
                if h == "hh.ru" or h.endswith(".hh.ru"):
                    return "hh.ru"
                return h
            except Exception:
                return ""

        target_host = _extract_norm_host(clean_url)
        known_platform_names = {
            "hh.ru": "HeadHunter (hh.ru)",
            "linkedin.com": "LinkedIn",
            "indeed.com": "Indeed",
            "secure.indeed.com": "Indeed",
            "glassdoor.com": "Glassdoor",
            "djinni.co": "Djinni",
            "dou.ua": "DOU",
            "work.ua": "Work.ua",
            "robota.ua": "Robota.ua",
            "rabota.ua": "Robota.ua",
            "wellfound.com": "Wellfound",
            "welcometothejungle.com": "Welcome to the Jungle (Otta)",
            "otta.com": "Welcome to the Jungle (Otta)",
            "theladders.com": "Ladders",
            "dice.com": "Dice",
            "ziprecruiter.com": "ZipRecruiter",
            "monster.com": "Monster",
        }
        if target_host in known_platform_names and (
            not clean_name
            or clean_name.lower() in (target_host, f"www.{target_host}", "career portal", "sign in", "login", "вход")
        ):
            clean_name = known_platform_names[target_host]
        if target_host == "hh.ru" and ("/account/login" in clean_url.lower() or not clean_url):
            clean_url = "https://hh.ru"

        if not clean_name and clean_url:
            clean_name = target_host or clean_url
        if not clean_name:
            clean_name = "Career Portal"

        clean_user = username.strip() or str(
            raw.get("knowledge_base", {}).get("profile_header", {}).get("email")
            or "alex.mercer@example.com"
        )

        # Match existing entry by id, or by normalized host + username when auto_registered or updating same site
        existing: dict[str, Any] | None = None
        if entry_id:
            existing = next((e for e in vault if isinstance(e, dict) and str(e.get("id", "")) == entry_id), None)
        if existing is None and (clean_url or target_host):
            for e in vault:
                if not isinstance(e, dict):
                    continue
                e_url = str(e.get("website_url", "")).strip()
                e_host = _extract_norm_host(e_url)
                if (
                    (e_url and clean_url and e_url.rstrip("/") == clean_url.rstrip("/"))
                    or (target_host and e_host == target_host and str(e.get("username", "")).lower() == clean_user.lower())
                    or (target_host and e_host == target_host and not e.get("username"))
                ):
                    existing = e
                    break

        desired_len = 12 if (adjust_to_12_chars or (max_length_hint is not None and 8 <= max_length_hint < 20)) else 20
        final_password = password.strip()
        if adjust_to_12_chars and (not final_password or len(final_password) > 12):
            final_password = self._generate_site_password(length=12)
        elif not final_password:
            if existing and existing.get("password") and not adjust_to_12_chars:
                final_password = str(existing["password"])
            else:
                final_password = self._generate_site_password(length=desired_len, max_length_hint=max_length_hint)

        pwd_len = len(final_password)
        final_desc = description.strip()
        if not final_desc:
            if existing and existing.get("description"):
                final_desc = str(existing["description"])
            elif auto_registered:
                final_desc = f"Auto-registered account ({pwd_len}-char password)"
            else:
                final_desc = f"Saved login ({pwd_len}-char password)"
        if adjust_to_12_chars and "12" not in final_desc:
            final_desc = f"{final_desc} — Auto-adjusted to 12 chars for platform limit"

        if existing is not None:
            existing["website_name"] = clean_name
            existing["website_url"] = clean_url or str(existing.get("website_url", ""))
            existing["username"] = clean_user
            existing["password"] = final_password
            existing["password_length"] = pwd_len
            if totp_token or "totp_token" not in existing:
                existing["totp_token"] = totp_token.strip()
            existing["totp_current_code"] = self._compute_totp_code(str(existing.get("totp_token", "")))
            existing["description"] = final_desc
            if auto_registered:
                existing["auto_registered"] = True
            existing["updated_at"] = ts_str
            target_entry = existing
        else:
            target_entry = {
                "id": entry_id or f"pwd_{uuid.uuid4().hex[:10]}",
                "website_name": clean_name,
                "website_url": clean_url,
                "username": clean_user,
                "password": final_password,
                "password_length": pwd_len,
                "totp_token": totp_token.strip(),
                "totp_current_code": self._compute_totp_code(totp_token.strip()),
                "description": final_desc,
                "auto_registered": bool(auto_registered),
                "created_at": ts_str,
                "updated_at": ts_str,
            }
            vault.insert(0, target_entry)

        try:
            self.secret_store.store_secret("PASSWORD_VAULT_JSON", json.dumps(vault, ensure_ascii=False))
        except Exception:
            pass
        return target_entry

    @staticmethod
    def _mask_real_key(key: str) -> str:
        k = key.strip()
        if k.startswith("sk-or-v1-") and len(k) > 17:
            return f"{k[:13]}••••{k[-4:]}"
        if k.startswith("sk-or-") and len(k) > 14:
            return f"{k[:10]}••••{k[-4:]}"
        if k.upper().startswith("CAP-") and len(k) > 12:
            return f"{k[:8]}••••{k[-4:]}"
        if len(k) > 10:
            return f"{k[:6]}••••{k[-4:]}"
        if len(k) > 4:
            return f"{k[:2]}••••{k[-2:]}"
        return k

    def _snapshot_loaded_outreach_ids(self, obj: dict[str, Any]) -> None:
        snap = {
            "queued_ids": {
                str(q.get("id"))
                for q in obj.get("queued_outreach_messages", [])
                if isinstance(q, dict) and q.get("id")
            },
            "event_ids": {
                str(e.get("id"))
                for e in obj.get("outreach_events", [])
                if isinstance(e, dict) and e.get("id")
            },
            "conv_msg_ids": {
                str(c.get("id")): {
                    str(m.get("id"))
                    for m in (c.get("messages") or [])
                    if isinstance(m, dict) and m.get("id")
                }
                for c in obj.get("conversation_threads", [])
                if isinstance(c, dict) and c.get("id")
            },
            "removed_threads": {
                str(x) for x in obj.get("removed_outreach_threads", []) if str(x).strip()
            },
        }
        snap_map: dict[int, dict[str, Any]] = getattr(self, "_snapshot_by_state_id", {})
        if len(snap_map) > 32:
            snap_map.clear()
        snap_map[id(obj)] = snap
        self._snapshot_by_state_id = snap_map
        self._latest_outreach_snapshot = snap

    def _load_raw_state(self) -> dict[str, Any]:
        last_err: Exception | None = None
        for attempt in range(3):
            try:
                text = self.state_file.read_text(encoding="utf-8", errors="ignore")
            except OSError as exc:
                last_err = exc
                time.sleep(0.03)
                continue
            stripped = text.lstrip()
            if not stripped:
                time.sleep(0.03)
                continue
            try:
                obj = json.loads(stripped)
                if isinstance(obj, dict):
                    self._snapshot_loaded_outreach_ids(obj)
                    return obj
            except json.JSONDecodeError as exc:
                last_err = exc
                try:
                    obj, _ = json.JSONDecoder().raw_decode(stripped)
                    if isinstance(obj, dict):
                        self._snapshot_loaded_outreach_ids(obj)
                        self._save_raw_state(obj)
                        return obj
                except Exception as inner_exc:
                    last_err = inner_exc
                    time.sleep(0.03)
        if last_err is not None:
            raise last_err
        self._snapshot_loaded_outreach_ids({})
        return {}

    def _merge_concurrent_disk_outreach_updates(self, state: dict[str, Any], disk_obj: dict[str, Any]) -> None:
        """Preserve any outreach messages/threads queued or sent by a concurrent process since this state dict was loaded."""
        snap_map: dict[int, dict[str, Any]] = getattr(self, "_snapshot_by_state_id", {})
        snap = snap_map.get(id(state)) or getattr(self, "_latest_outreach_snapshot", {})
        loaded_q_ids: set[str] = snap.get("queued_ids", set())
        loaded_ev_ids: set[str] = snap.get("event_ids", set())
        loaded_conv_msgs: dict[str, set[str]] = snap.get("conv_msg_ids", {})
        loaded_removed: set[str] = snap.get("removed_threads", set())

        # 1. Merge newly added queued_outreach_messages from disk
        cur_q_list = state.setdefault("queued_outreach_messages", [])
        cur_q_ids = {str(q.get("id")) for q in cur_q_list if isinstance(q, dict) and q.get("id")}
        for dq in disk_obj.get("queued_outreach_messages", []):
            if not isinstance(dq, dict):
                continue
            dq_id = str(dq.get("id") or "")
            if dq_id and dq_id not in cur_q_ids and dq_id not in loaded_q_ids:
                cur_q_list.append(dq)
                cur_q_ids.add(dq_id)

        # 2. Merge newly added outreach_events from disk
        cur_ev_list = state.setdefault("outreach_events", [])
        cur_ev_ids = {str(e.get("id")) for e in cur_ev_list if isinstance(e, dict) and e.get("id")}
        new_disk_evs = []
        for de in disk_obj.get("outreach_events", []):
            if not isinstance(de, dict):
                continue
            de_id = str(de.get("id") or "")
            if de_id and de_id not in cur_ev_ids and de_id not in loaded_ev_ids:
                new_disk_evs.append(de)
                cur_ev_ids.add(de_id)
        if new_disk_evs:
            cur_ev_list[:0] = new_disk_evs

        # 3. Merge newly added conversation_threads and messages from disk
        cur_conv_list = state.setdefault("conversation_threads", [])
        cur_conv_by_id = {str(c.get("id")): c for c in cur_conv_list if isinstance(c, dict) and c.get("id")}
        for dc in disk_obj.get("conversation_threads", []):
            if not isinstance(dc, dict):
                continue
            dc_id = str(dc.get("id") or "")
            if not dc_id:
                continue
            if dc_id not in cur_conv_by_id:
                if dc_id not in loaded_conv_msgs:
                    cur_conv_list.insert(0, dc)
                    cur_conv_by_id[dc_id] = dc
            else:
                target_c = cur_conv_by_id[dc_id]
                target_msgs = target_c.setdefault("messages", [])
                target_msg_ids = {str(m.get("id")) for m in target_msgs if isinstance(m, dict) and m.get("id")}
                prior_msg_ids = loaded_conv_msgs.get(dc_id, set())
                appended_any = False
                for dm in dc.get("messages", []):
                    if not isinstance(dm, dict):
                        continue
                    dm_id = str(dm.get("id") or "")
                    if dm_id and dm_id not in target_msg_ids and dm_id not in prior_msg_ids:
                        target_msgs.append(dm)
                        target_msg_ids.add(dm_id)
                        appended_any = True
                if appended_any:
                    if dc.get("delivery_state"):
                        target_c["delivery_state"] = dc["delivery_state"]
                    if dc.get("last_activity_at"):
                        target_c["last_activity_at"] = dc["last_activity_at"]
                    target_c["draft_text"] = dc.get("draft_text", target_c.get("draft_text", ""))

        # 4. Merge newly removed threads from disk
        cur_rem_list = state.setdefault("removed_outreach_threads", [])
        cur_rem_set = {str(x) for x in cur_rem_list if str(x).strip()}
        for dr in disk_obj.get("removed_outreach_threads", []):
            dr_s = str(dr or "").strip()
            if dr_s and dr_s not in cur_rem_set and dr_s not in loaded_removed:
                cur_rem_list.append(dr_s)
                cur_rem_set.add(dr_s)

    def _save_raw_state(self, state: dict[str, Any]) -> None:
        import fcntl

        self.state_file.parent.mkdir(parents=True, exist_ok=True)
        lock_path = self.state_file.with_name(f".{self.state_file.name}.lock")
        tmp_path = self.state_file.with_name(f".{self.state_file.name}.{os.getpid()}.{uuid.uuid4().hex[:8]}.tmp")
        lock_fd: int | None = None
        try:
            try:
                lock_fd = os.open(str(lock_path), os.O_CREAT | os.O_RDWR, 0o600)
                fcntl.flock(lock_fd, fcntl.LOCK_EX)
            except OSError:
                lock_fd = None

            try:
                if self.state_file.exists():
                    disk_txt = self.state_file.read_text(encoding="utf-8", errors="ignore").lstrip()
                    if disk_txt:
                        disk_obj = json.loads(disk_txt)
                        if isinstance(disk_obj, dict):
                            self._merge_concurrent_disk_outreach_updates(state, disk_obj)
            except Exception:
                pass

            payload = json.dumps(state, indent=2, sort_keys=True)
            tmp_path.write_text(payload, encoding="utf-8")
            os.replace(tmp_path, self.state_file)
            self._snapshot_loaded_outreach_ids(state)
        finally:
            if tmp_path.exists():
                try:
                    tmp_path.unlink()
                except OSError:
                    pass
            if lock_fd is not None:
                try:
                    fcntl.flock(lock_fd, fcntl.LOCK_UN)
                except OSError:
                    pass
                try:
                    os.close(lock_fd)
                except OSError:
                    pass

    def _list_facts(self) -> list[dict[str, Any]]:
        rows = self.candidate_store._conn.execute(
            "SELECT * FROM candidate_facts ORDER BY version DESC, key ASC"
        ).fetchall()
        result: list[dict[str, Any]] = []
        for r in rows:
            result.append(
                {
                    "id": r["id"],
                    "key": r["key"],
                    "category": r["category"],
                    "value": json.loads(r["value_json"]),
                    "source_type": r["source_type"],
                    "source_ref": r["source_ref"],
                    "confidence": float(r["confidence"]),
                    "confirmed": bool(r["confirmed"]),
                    "scope_level": r["scope_level"],
                    "scope_country": r["scope_country"] or "GLOBAL",
                    "effective_from": r["effective_from"],
                    "supersedes_id": r["supersedes_id"],
                    "superseded_by_id": r["superseded_by_id"],
                    "version": int(r["version"]),
                }
            )
        return result

    def _upsert_confirmed_fact(
        self,
        *,
        key: str,
        category: str,
        value: Any,
        source_type: str = "user_confirmed",
        source_ref: str = "knowledge_base",
        country: str = "GLOBAL",
    ) -> str:
        now_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        scope = (
            FactScope(level=ScopeLevel.GLOBAL)
            if country == "GLOBAL"
            else FactScope(level=ScopeLevel.COUNTRY, country=country)
        )
        existing = self.candidate_store._conn.execute(
            "SELECT id FROM candidate_facts WHERE key = ? AND superseded_by_id IS NULL",
            (key,),
        ).fetchone()
        inp = CandidateFactInput(
            key=key,
            category=category,
            value=value,
            source_type=source_type,
            source_ref=source_ref,
            confidence=1.0,
            confirmed=True,
            scope=scope,
            effective_from=now_str,
        )
        if existing is not None:
            return self.candidate_store.supersede_fact(prior_fact_id=existing["id"], new_input=inp)
        return self.candidate_store.add_fact(inp)

    def _list_hard_bounces(self) -> list[dict[str, str]]:
        rows = self.no_send_register._conn.execute(
            "SELECT email, application_id, smtp_diagnostic, recorded_at FROM hard_bounce_no_send ORDER BY recorded_at DESC"
        ).fetchall()
        return [
            {
                "email": r[0],
                "application_id": r[1],
                "smtp_diagnostic": r[2],
                "recorded_at": r[3],
            }
            for r in rows
        ]

    def _load_gates(self) -> list[dict[str, Any]]:
        candidates = [
            Path(os.environ.get("AUTOAPPLY_RESOURCES_DIR", "")) / "docs" / "release" / "gates.json",
            Path(__file__).resolve().parents[2] / "docs" / "release" / "gates.json",
        ]
        for p in candidates:
            if p.is_file():
                data = json.loads(p.read_text(encoding="utf-8"))
                return list(data.get("gates", []))
        return []

    def _find_bundled_resources_dir(self) -> Path | None:
        env_res = os.environ.get("AUTOAPPLY_RESOURCES_DIR", "").strip()
        if env_res and Path(env_res).is_dir():
            return Path(env_res).resolve()
        # Check relative to runtime/autoapply/app_bridge.py inside AutoApply.app/Contents/Resources/runtime/autoapply
        candidate = Path(__file__).resolve().parents[2]
        if (candidate / "Browser").is_dir() or (candidate / "extensions").is_dir():
            return candidate
        return None

    def _inspect_components_on_disk(self) -> list[dict[str, str]]:
        res_dir = self._find_bundled_resources_dir()
        bundled_aa_browser = (
            res_dir / "Browser" / "AutoApply Browser.app" / "Contents" / "MacOS" / "AutoApply Browser"
            if res_dir
            else None
        )
        bundled_browser = (
            res_dir / "Browser" / "Chromium.app" / "Contents" / "MacOS" / "Chromium"
            if res_dir
            else None
        )
        local_aa_browser = (
            self.root / "browser-bin" / "AutoApply Browser.app" / "Contents" / "MacOS" / "AutoApply Browser"
        )
        local_browser_chromium = (
            self.root / "browser-bin" / "Chromium.app" / "Contents" / "MacOS" / "Chromium"
        )
        local_browser_legacy = (
            self.root / "browser-bin" / "CloakBrowser.app" / "Contents" / "MacOS" / "Chromium"
        )

        browser_status = "not_installed"
        browser_version = "Not installed"
        browser_source = str(self.root / "browser-bin" / "AutoApply Browser.app")

        if bundled_aa_browser and bundled_aa_browser.is_file():
            browser_status = "ready"
            browser_version = "Browser Ready"
            browser_source = str(bundled_aa_browser.parents[2])
        elif local_aa_browser.is_file():
            browser_status = "ready"
            browser_version = "Browser Ready"
            browser_source = str(local_aa_browser.parents[2])
        elif bundled_browser and bundled_browser.is_file():
            browser_status = "ready"
            browser_version = "Browser Ready"
            browser_source = str(bundled_browser.parents[2])
        elif local_browser_chromium.is_file():
            browser_status = "ready"
            browser_version = "Browser Ready"
            browser_source = str(local_browser_chromium.parents[2])
        elif local_browser_legacy.is_file():
            browser_status = "ready"
            browser_version = "Browser Ready"
            browser_source = str(local_browser_legacy.parents[2])
        else:
            try:
                import cloakbrowser

                info = cloakbrowser.binary_info()
                if info.get("installed") and Path(str(info.get("binary_path", ""))).is_file():
                    browser_status = "installed_in_cache"
                    browser_version = "Browser Ready (Click Set Up to finish)"
                    browser_source = str(info.get("binary_path"))
            except Exception:
                pass

        # 2. Local Engine Config
        hermes_cfg = self.root / "runtime-state" / "hermes" / "config.json"
        hermes_status = "ready" if hermes_cfg.is_file() else "not_installed"

        # 3. Local Keychain Security
        sops_bin = self.root / "bin" / "sops"
        age_bin = self.root / "bin" / "age"
        bundled_sops = (res_dir / "bin" / "sops") if res_dir else None
        sys_sops = Path("/opt/homebrew/bin/sops")
        sys_age = Path("/opt/homebrew/bin/age")
        sops_ready = (
            (sops_bin.is_file() and age_bin.is_file())
            or (bundled_sops is not None and bundled_sops.is_file())
            or (sys_sops.is_file() and sys_age.is_file() and self.secret_store.envelope_path.is_file())
        )

        # 4. Separate Browser Profiles
        profiles_root = self.root / "browser-profiles"
        required_partitions = (
            "ats_ephemeral",
            "google_mail",
            "teal",
            "linkedin",
            "extension_automation",
        )
        profiles_ready = all((profiles_root / p).is_dir() for p in required_partitions)

        # 5. Official Capcha Solver Extension + AutoApply Companion Extension
        ext_manifest = self.root / "extensions" / "capsolver" / "manifest.json"
        ext_bg = self.root / "extensions" / "capsolver" / "background.js"
        ext_ready = ext_manifest.is_file() and ext_bg.is_file() and ext_bg.stat().st_size > 1000

        return [
            {
                "id": "browser_binary",
                "name": "Browser",
                "source": browser_source,
                "version": browser_version,
                "size": "Included",
                "status": "ready" if browser_status == "ready" else "needs_install",
            },
            {
                "id": "capsolver_ext",
                "name": "Companion & Capcha Solver Extensions",
                "source": str(ext_manifest.parent),
                "version": "Preloaded Side Guide & Pinned Auto-Captcha",
                "size": "Included",
                "status": "ready" if ext_ready else "needs_install",
            },
            {
                "id": "browser_profiles",
                "name": "Browser Sessions",
                "source": str(profiles_root),
                "version": "Gmail, Teal, LinkedIn & Job Applications",
                "size": "Ready",
                "status": "ready" if profiles_ready else "needs_install",
            },
            {
                "id": "sops_age",
                "name": "Local Keychain Security",
                "source": str(self.secret_store.envelope_path),
                "version": "Encrypted on Your Mac",
                "size": "Protected",
                "status": "ready" if sops_ready else "needs_install",
            },
            {
                "id": "hermes_runtime",
                "name": "Local AI & Voice Engine",
                "source": str(hermes_cfg.parent),
                "version": "Ready on Your Mac (English Speech + AI)",
                "size": "Included",
                "status": "ready" if hermes_status == "ready" else "needs_install",
            },
        ]

    @staticmethod
    def _version_tuple(version_str: str) -> tuple[int, ...]:
        cleaned = str(version_str or "0.0.0").strip().lstrip("vV")
        parts: list[int] = []
        for token in re.split(r"[^0-9]+", cleaned):
            if token:
                try:
                    parts.append(int(token))
                except ValueError:
                    pass
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts[:4])

    def _is_force_update_required(self, onb: dict[str, Any]) -> bool:
        if not isinstance(onb, dict):
            return False
        upd = onb.get("update_config")
        if not isinstance(upd, dict):
            return False
        cur_ver = str(upd.get("current_version") or "0.1.0").strip()
        latest_ver = str(upd.get("latest_version") or cur_ver).strip()
        min_req_ver = str(upd.get("minimum_required_version") or cur_ver).strip()
        is_newer = self._version_tuple(latest_ver) > self._version_tuple(cur_ver)
        below_min = self._version_tuple(cur_ver) < self._version_tuple(min_req_ver)
        flag_required = bool(upd.get("update_required") or upd.get("force_update_required"))
        return bool(below_min or (is_newer and flag_required))

    def _is_licensing_limits_enforced(self, onb: dict[str, Any] | None = None) -> bool:
        """Return True once the payment gateway is live and licensing limits are enforced; False during the pre-gateway Trial Mode period."""
        env_val = os.getenv("AUTOAPPLY_ENFORCE_LICENSING_LIMITS", "").strip().lower()
        if env_val in ("1", "true", "yes", "on"):
            return True
        if env_val in ("0", "false", "no", "off"):
            return False
        if isinstance(onb, dict) and "licensing_limits_enforced" in onb:
            return bool(onb.get("licensing_limits_enforced"))
        return False

    def _is_license_or_trial_expired(self, onb: dict[str, Any], now: datetime | None = None) -> bool:
        if not isinstance(onb, dict):
            return False
        current = now or datetime.now(timezone.utc)
        trial_state = str(onb.get("trial_state") or "").strip()
        exp_str = str(onb.get("trial_expires_at") or "").strip()

        if trial_state in ("paid_key_active", "paid_active"):
            if exp_str:
                try:
                    parsed = datetime.fromisoformat(exp_str.replace("Z", "+00:00"))
                    if parsed.tzinfo is None:
                        parsed = parsed.replace(tzinfo=timezone.utc)
                    return current >= parsed
                except Exception:
                    return False
            return False

        if trial_state == "expired":
            return True

        # While the payment gateway is not yet live (and not an explicit time-travel test), keep Trial Mode active
        if now is None and not self._is_licensing_limits_enforced(onb):
            return False

        if exp_str:
            try:
                parsed = datetime.fromisoformat(exp_str.replace("Z", "+00:00"))
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                if current >= parsed:
                    return True
            except Exception:
                pass

        try:
            access = self.entitlement_service.evaluate_access(device_id="mac_local_device", current_time=current)
            if access.status == "expired":
                return True
        except Exception:
            pass
        return False

