    _CODEX_WIRE_SLUGS = frozenset(item["wire_slug"] for item in OPENAI_CODEX_MODEL_CATALOG)

    @classmethod
    def _is_codex_model(cls, slug: str) -> bool:
        s = str(slug or "").strip().lower()
        if not s:
            return False
        if s.startswith("openai-codex/") or s == "openai/codex-commercial-session" or "codex" in s:
            return True
        bare = s.split("/")[-1].removesuffix("-900k")
        return bare in cls._CODEX_WIRE_SLUGS

    @classmethod
    def _normalize_codex_model_id(cls, slug: str) -> str:
        raw_s = str(slug or "").strip()
        if not raw_s:
            return "~deepseek/deepseek-flash-latest"
        s = raw_s.lower()
        if s in ("openai/codex-commercial-session", "codex", "chatgpt", "openai-codex", "openai-codex/default"):
            return cls.OPENAI_CODEX_DEFAULT_MODEL
        if s.startswith("openai-codex/"):
            tail = s.split("/", 1)[1].strip()
            bare = tail.removesuffix("-900k")
            if bare in cls._CODEX_WIRE_SLUGS:
                return f"openai-codex/{tail}"
            return cls.OPENAI_CODEX_DEFAULT_MODEL
        bare = s.split("/")[-1].removesuffix("-900k")
        if bare in cls._CODEX_WIRE_SLUGS:
            return f"openai-codex/{s.split('/')[-1]}"
        return raw_s

    @classmethod
    def _codex_wire_slug(cls, slug: str) -> str:
        norm = cls._normalize_codex_model_id(slug)
        if norm.lower().startswith("openai-codex/"):
            tail = norm.split("/", 1)[1].strip().lower().removesuffix("-900k")
            if tail in cls._CODEX_WIRE_SLUGS:
                return tail
        return "gpt-6.1-sol"

    @classmethod
    def _get_model_runtime_specs(cls, slug: str, effort: str = "medium") -> dict[str, Any]:
        eff = str(effort or "medium").strip().lower()
        if eff not in ("low", "medium", "high"):
            eff = "medium"
        if cls._is_codex_model(slug):
            norm_id = cls._normalize_codex_model_id(slug)
            wire = cls._codex_wire_slug(norm_id)
            entry = next((m for m in cls.OPENAI_CODEX_MODEL_CATALOG if m["wire_slug"] == wire), cls.OPENAI_CODEX_MODEL_CATALOG[0])
            return {
                "id": norm_id,
                "wire_slug": wire,
                "friendly_name": f"{entry['display_name']} (OpenAI Codex)",
                "display_name": entry["display_name"],
                "provider_short": "OpenAI Codex (ChatGPT Subscription OAuth)",
                "provider_full": "OpenAI Codex (ChatGPT Subscription OAuth — Direct via chatgpt.com/backend-api/codex, NOT OpenRouter)",
                "context_window": entry["context_window"],
                "max_context_window": entry["max_context_window"],
                "context_label": entry["context_label"],
                "effort": eff,
                "is_codex": True,
            }
        clean_id = str(slug or "~deepseek/deepseek-flash-latest").strip()
        s_low = clean_id.lstrip("~").lower()
        openrouter_ctx = {
            "deepseek/deepseek-flash-latest": (128000, "128,000 tokens (128K context window)"),
            "deepseek/deepseek-pro-latest": (128000, "128,000 tokens (128K context window)"),
            "deepseek/deepseek-chat": (128000, "128,000 tokens (128K context window)"),
            "deepseek/deepseek-r1": (128000, "128,000 tokens (128K context window)"),
            "anthropic/claude-sonnet-latest": (200000, "200,000 tokens (200K context window)"),
            "anthropic/claude-sonnet-4.6": (200000, "200,000 tokens (200K context window)"),
            "anthropic/claude-3.7-sonnet": (200000, "200,000 tokens (200K context window)"),
            "google/gemini-2.5-flash": (1048576, "1,048,576 tokens (1M context window)"),
            "google/gemini-2.5-pro": (1048576, "1,048,576 tokens (1M context window)"),
            "openai/gpt-4.1": (1047576, "1,047,576 tokens (1M context window)"),
            "openai/gpt-4.1-mini": (1047576, "1,047,576 tokens (1M context window)"),
            "openai/gpt-5.4": (400000, "400,000 tokens (400K context window)"),
            "qwen/qwen-2.5-72b-instruct": (131072, "131,072 tokens (128K context window)"),
            "meta-llama/llama-3.3-70b-instruct": (131072, "131,072 tokens (128K context window)"),
        }
        ctx_num, ctx_lbl = openrouter_ctx.get(s_low, (128000, "128,000 tokens (128K context window)"))
        fname = cls._friendly_model_name(clean_id)
        return {
            "id": clean_id,
            "wire_slug": clean_id,
            "friendly_name": fname,
            "display_name": fname,
            "provider_short": "OpenRouter",
            "provider_full": "OpenRouter (openrouter.ai/api/v1)",
            "context_window": ctx_num,
            "max_context_window": ctx_num,
            "context_label": ctx_lbl,
            "effort": eff,
            "is_codex": False,
        }

