    def _load_periodic_tasks_raw(self) -> list[dict[str, Any]]:
        candidates = [
            Path.home() / ".hermes" / "profiles" / "vb-jobs" / "cron" / "jobs.json",
            self.root / "runtime-state" / "hermes" / "cron" / "jobs.json",
        ]
        for p in candidates:
            try:
                if p.is_file():
                    data = json.loads(p.read_text(encoding="utf-8"))
                    jobs = data.get("jobs", [])
                    if isinstance(jobs, list) and jobs:
                        return jobs
            except Exception:
                pass
        return self._default_periodic_tasks_catalog()

    def _humanize_periodic_frequency(self, schedule: dict[str, Any] | None, schedule_display: str) -> str:
        sched = schedule if isinstance(schedule, dict) else {}
        kind = str(sched.get("kind") or "").strip().lower()
        minutes = sched.get("minutes")
        if kind == "interval" and isinstance(minutes, (int, float)) and minutes > 0:
            mins = int(minutes)
            if mins == 1:
                return "Every 1 min"
            if mins < 60:
                return f"Every {mins} min"
            if mins == 60:
                return "Every 1 hour"
            if mins % 60 == 0:
                hrs = mins // 60
                return f"Every {hrs} hours"
            return f"Every {mins} min"
        raw_disp = str(schedule_display or sched.get("display") or "").strip()
        if raw_disp.lower().startswith("every "):
            token = raw_disp[6:].strip().lower()
            if token.endswith("m") and token[:-1].isdigit():
                mins = int(token[:-1])
                if mins == 1:
                    return "Every 1 min"
                if mins < 60:
                    return f"Every {mins} min"
                if mins == 60:
                    return "Every 1 hour"
                if mins % 60 == 0:
                    return f"Every {mins // 60} hours"
                return f"Every {mins} min"
            if token.endswith("h") and token[:-1].isdigit():
                hrs = int(token[:-1])
                return "Every 1 hour" if hrs == 1 else f"Every {hrs} hours"
        if "once in " in raw_disp.lower():
            suffix = raw_disp.lower().split("once in ", 1)[1].strip()
            if suffix.endswith("d") and suffix[:-1].isdigit():
                return f"In {suffix[:-1]} days (Scheduled)"
            return f"In {suffix} (Scheduled)"
        if kind == "once" or raw_disp.lower().startswith("once"):
            run_at = str(sched.get("run_at") or "").strip()
            if run_at:
                return f"Scheduled ({run_at[:10]})"
            return "One-Time Scheduled Task"
        return "Periodic Schedule"

