    def _resolve_hh_vacancy_url_for_company(self, company: str) -> str:
        comp_l = str(company or "").strip().lower()
        if not comp_l:
            return ""
        if comp_l in self._HH_VACANCY_URL_BY_COMPANY:
            return self._HH_VACANCY_URL_BY_COMPANY[comp_l]
        for k, v in self._HH_VACANCY_URL_BY_COMPANY.items():
            if k in comp_l or comp_l in k:
                return v
        return ""

    def _resolve_hh_thread_url_for_outreach(self, *, custom_url: str, payload: dict[str, Any]) -> str:
        """Resolve an HH outreach thread to its exact HH Chat URL (https://hh.ru/chat/<id>) or specific vacancy chat URL."""
        candidates = [
            str(custom_url or "").strip(),
            str(payload.get("contact_handle") or "").strip(),
            str(payload.get("profile_url") or "").strip(),
            str(payload.get("thread_id") or "").strip(),
        ]
        # 1. Check if any candidate already has an explicit /chat/<id> URL
        for cand in candidates:
            m_chat = re.search(r"hh\.ru/chat/(\d+)", cand, re.I)
            if m_chat:
                return f"https://hh.ru/chat/{m_chat.group(1)}"

        # 2. Check if any candidate has a /vacancy/<id> or hh_<id> and map to direct chat URL if known
        found_vacancy_id = ""
        for cand in candidates:
            m_vac = re.search(r"(?:/vacancy/|hh_)(\d{6,})", cand, re.I)
            if m_vac:
                vid = m_vac.group(1)
                if vid in self._HH_CHAT_URL_BY_VACANCY_ID:
                    return self._HH_CHAT_URL_BY_VACANCY_ID[vid]
                if not found_vacancy_id:
                    found_vacancy_id = vid

        # 3. Check company name mapping for direct chat URL
        comp_l = str(payload.get("company") or "").strip().lower()
        if comp_l:
            if comp_l in self._HH_CHAT_URL_BY_COMPANY:
                return self._HH_CHAT_URL_BY_COMPANY[comp_l]
            for k, v in self._HH_CHAT_URL_BY_COMPANY.items():
                if k in comp_l or comp_l in k:
                    return v

        # 4. Fall back to specific vacancy URL (which _open_hh_chat_in_tab automatically opens into the HH chat)
        if found_vacancy_id:
            return f"https://hh.ru/vacancy/{found_vacancy_id}"
        vac_by_comp = self._resolve_hh_vacancy_url_for_company(comp_l)
        if vac_by_comp:
            return vac_by_comp

        url_s = str(custom_url or "").strip()
        if url_s and "hh.ru" in url_s.lower() and "applicant/negotiations" not in url_s.lower() and url_s.rstrip("/") != "https://chatik.hh.ru":
            return url_s
        return "https://hh.ru/chat"

    def _open_hh_chat_in_tab(self, port: int, tab_id: str, target_url: str, company_hint: str = "") -> None:
        """Connect to the opened HH tab via CDP and open the real HH Chat for the vacancy/thread."""
        import time

        comp_js = json.dumps(str(company_hint or "").strip().lower())
        js_open_hh_chat = f"""
        (() => {{
            const href = window.location.href || "";
            // Already on a specific full-page HH chat (/chat/<id>)
            if (/\\/chat\\/\\d+/.test(href)) {{
                return "already_in_chat";
            }}
            // If an open chatik iframe with /chat/<id> is already present on a vacancy/negotiations page, navigate directly to full-screen HH chat
            const chatIframes = Array.from(document.querySelectorAll('iframe'))
                .map(f => f.src || "")
                .filter(s => /\\/chat\\/\\d+/.test(s));
            if (chatIframes.length > 0) {{
                const m = chatIframes[0].match(/\\/chat\\/(\\d+)/);
                if (m && m[1]) {{
                    window.location.href = "https://hh.ru/chat/" + m[1];
                    return "redirected_to_chat_" + m[1];
                }}
            }}
            // On a vacancy page (/vacancy/<id>), click the "Chat" / "Чат" button to open the employer chat topic
            const vacChatBtn = document.querySelector('[data-qa="vacancy-response-link-view-topic"], a[href*="chatik.hh.ru"], a[href*="/chat/"]');
            if (vacChatBtn && !window.__aaVacChatClicked) {{
                window.__aaVacChatClicked = true;
                vacChatBtn.click();
                return "clicked_vacancy_chat_btn";
            }}
            // On negotiations page, match company card and click open_chat
            const compHint = {comp_js};
            const items = Array.from(document.querySelectorAll('[data-qa="negotiations-item"]'));
            if (items.length > 0) {{
                for (const item of items) {{
                    const text = (item.innerText || "").toLowerCase();
                    if (!compHint || text.includes(compHint)) {{
                        const btn = item.querySelector('[data-qa="open_chat"]');
                        if (btn && !window.__aaNegChatClicked) {{
                            window.__aaNegChatClicked = true;
                            btn.click();
                            return "clicked_negotiations_chat_btn";
                        }}
                    }}
                }}
            }}
            return "waiting";
        }})()
        """

        for attempt in range(14):
            time.sleep(0.8 if attempt > 0 else 1.0)
            try:
                tabs = self._get_live_cdp_tabs(port)
                target_tab = None
                if tab_id:
                    target_tab = next((t for t in tabs if str(t.get("id") or "") == tab_id), None)
                if not target_tab:
                    target_tab = next(
                        (
                            t
                            for t in tabs
                            if str(t.get("type") or "") == "page" and "hh.ru" in str(t.get("url") or "").lower()
                        ),
                        None,
                    )
                if not target_tab or not target_tab.get("webSocketDebuggerUrl"):
                    continue
                ws_url = str(target_tab["webSocketDebuggerUrl"])

                async def _eval_hh() -> str:
                    import websockets

                    async with websockets.connect(ws_url, open_timeout=1.5, close_timeout=0.8) as ws:
                        await ws.send(
                            json.dumps(
                                {
                                    "id": 1,
                                    "method": "Runtime.evaluate",
                                    "params": {"expression": js_open_hh_chat, "returnByValue": True},
                                }
                            )
                        )
                        raw_msg = json.loads(await asyncio.wait_for(ws.recv(), timeout=2.5))
                        return str(raw_msg.get("result", {}).get("result", {}).get("value") or "")

                status = asyncio.run(_eval_hh())
                if status == "already_in_chat" or status.startswith("redirected_to_chat_"):
                    return
            except Exception:
                continue

    def _resolve_linkedin_thread_url_for_outreach(
        self,
        *,
        custom_url: str,
        payload: dict[str, Any],
        raw: dict[str, Any] | None = None,
    ) -> str:
        """Resolve a LinkedIn outreach thread to its exact person-specific LinkedIn thread or profile URL."""
        def _norm_li_url(u: str) -> str:
            s = str(u or "").strip()
            if not s:
                return ""
            if "linkedin.com/" in s.lower() and not s.lower().startswith(("http://", "https://")):
                s = f"https://www.{s.lstrip('/')}" if not s.lower().startswith("www.") else f"https://{s}"
            return s

        contact_name = str(payload.get("contact_name") or "").strip()
        company_name = str(payload.get("company") or "").strip()
        thread_id = str(payload.get("thread_id") or payload.get("id") or "").strip()

        candidates: list[str] = [
            _norm_li_url(custom_url),
            _norm_li_url(str(payload.get("thread_url") or "")),
            _norm_li_url(str(payload.get("profile_url") or "")),
            _norm_li_url(str(payload.get("contact_handle") or "")),
        ]

        # Known live LinkedIn thread readback for Niklas Huetzen
        if (
            "niklas" in contact_name.lower()
            or "niklas-huetzen" in " ".join(candidates).lower()
            or "niklas_huetzen" in thread_id.lower()
        ):
            niklas_path = (
                Path.home() / "Hermes" / "job-applications" / "linkedin-resume-request-20261018" / "niklas-live-thread-readback.json"
            )
            if niklas_path.exists():
                try:
                    nk_data = json.loads(niklas_path.read_text(encoding="utf-8"))
                    nk_url = _norm_li_url(str(nk_data.get("url") or ""))
                    if "linkedin.com/messaging/thread/" in nk_url.lower():
                        candidates.insert(0, nk_url)
                except Exception:
                    pass
            candidates.append("https://www.linkedin.com/messaging/thread/2-ZjVkMDBlMzUtZDk0OC00ZDM2LThkYjItNjZhMDEwYzFjMjFkXzEwMA==/?searchTerm=Niklas%20Huetzen")
            candidates.append("https://www.linkedin.com/in/niklas-huetzen")

        # Also check raw state for any stored thread/event matching this contact or thread_id
        if isinstance(raw, dict):
            c_low = contact_name.lower()
            for ct in raw.get("conversation_threads", []):
                if not isinstance(ct, dict):
                    continue
                ct_id = str(ct.get("id") or "").strip()
                ct_cname = str(ct.get("contact_name") or "").strip().lower()
                if (thread_id and ct_id == thread_id) or (c_low and ct_cname == c_low):
                    for fld in ("thread_url", "profile_url", "contact_handle"):
                        v = _norm_li_url(str(ct.get(fld) or ""))
                        if v:
                            candidates.append(v)
            for ev in raw.get("outreach_events", []):
                if not isinstance(ev, dict):
                    continue
                ev_cname = str(ev.get("contact_name") or "").strip().lower()
                if c_low and ev_cname == c_low:
                    for fld in ("thread_url", "contact_url", "contact_value"):
                        v = _norm_li_url(str(ev.get(fld) or ""))
                        if v:
                            candidates.append(v)

        # Priority 1: Specific LinkedIn messaging thread URL (/messaging/thread/<id>)
        for cand in candidates:
            if "linkedin.com/messaging/thread/" in cand.lower():
                if (
                    contact_name
                    and "hiring team" not in contact_name.lower()
                    and contact_name.lower() not in ("linkedin contact", "employer", "target employer")
                    and "searchterm=" not in cand.lower()
                ):
                    sep = "&" if "?" in cand else "?"
                    return f"{cand}{sep}searchTerm={urllib.parse.quote(contact_name)}"
                return cand

        # Priority 2: Specific LinkedIn person profile (/in/<slug>) or post URL (/posts/<slug>_...)
        for cand in candidates:
            c_l = cand.lower()
            if "linkedin.com/in/" in c_l and "alex-mercer" not in c_l and "alexander-mercer" not in c_l:
                return cand
            m_post = re.search(r"linkedin\.com/posts/([a-zA-Z0-9\-]+?)_(?:[a-zA-Z0-9\-]+-)?activity-\d+", cand, re.I)
            if m_post:
                return f"https://www.linkedin.com/in/{m_post.group(1)}"

        # Priority 3: Specific LinkedIn company, job view, or talent page (/company/, /jobs/view/, /talent/)
        for cand in candidates:
            c_l = cand.lower()
            if (
                "linkedin.com/company/" in c_l
                or "linkedin.com/jobs/view/" in c_l
                or "linkedin.com/recruiter" in c_l
                or "linkedin.com/talent/" in c_l
            ):
                return cand

        # Priority 4: Person search on LinkedIn (never bare /messaging/ without a thread ID, which defaults to top unrelated inbox chat)
        clean_cname = contact_name if ("hiring team" not in contact_name.lower() and contact_name.lower() not in ("linkedin contact", "employer", "target employer")) else ""
        clean_comp = company_name if company_name.lower() not in ("hiring team", "linkedin contact", "employer", "target employer") else ""
        if clean_cname:
            q_str = f"{clean_cname} {clean_comp}".strip() if clean_comp and clean_comp.lower() not in clean_cname.lower() else clean_cname
            return f"https://www.linkedin.com/search/results/people/?keywords={urllib.parse.quote(q_str)}"
        if clean_comp:
            return f"https://www.linkedin.com/search/results/all/?keywords={urllib.parse.quote(clean_comp)}"

        # Priority 5: Any other LinkedIn URL if not bare /messaging/
        for cand in candidates:
            c_l = cand.lower().rstrip("/")
            if "linkedin.com/" in c_l and c_l not in ("https://www.linkedin.com/messaging", "https://linkedin.com/messaging"):
                return cand

        return "https://www.linkedin.com/messaging/"

    def _open_linkedin_chat_in_tab(
        self,
        port: int,
        tab_id: str,
        target_url: str,
        contact_hint: str = "",
        profile_hint: str = "",
    ) -> None:
        """Verify that an opened LinkedIn tab displays the intended contact; if LinkedIn Messaging defaulted to a different person, select the right thread or open their profile."""
        import time

        clean_contact = str(contact_hint or "").strip()
        clean_profile = str(profile_hint or "").strip()
        if clean_profile and "linkedin.com/" in clean_profile.lower() and not clean_profile.lower().startswith(("http://", "https://")):
            clean_profile = f"https://www.{clean_profile.lstrip('/')}"
        if not clean_contact or clean_contact.lower() in ("hiring team", "linkedin contact", "employer", "target employer"):
            return

        contact_js = json.dumps(clean_contact.lower())
        profile_js = json.dumps(clean_profile)
        js_verify_or_select_linkedin = f"""
        (() => {{
            const href = window.location.href || "";
            if (!href.includes("linkedin.com/messaging")) {{
                return "not_messaging_page";
            }}
            const targetName = {contact_js};
            const profileFallback = {profile_js};
            const firstToken = targetName.split(/\\s+/)[0] || targetName;

            // Check active conversation header
            const headerEl = document.querySelector(
                '.msg-entity-lockup__entity-title, .msg-thread__link-to-profile, h2.msg-entity-lockup__entity-title'
            );
            const activeTitle = ((headerEl && headerEl.innerText) || "").trim().toLowerCase();
            if (activeTitle && (activeTitle.includes(targetName) || (firstToken.length >= 3 && activeTitle.includes(firstToken)))) {{
                return "matched_active_thread";
            }}

            // Search left-rail conversation list items for targetName
            const items = Array.from(document.querySelectorAll(
                'li.msg-conversation-listitem, .msg-conversations-container__convo-item, [data-control-name="overlay.view_message"]'
            ));
            for (const item of items) {{
                const nameNode = item.querySelector('.msg-conversation-listitem__participant-names, .msg-conversation-card__participant-names, h3') || item;
                const txt = ((nameNode && nameNode.innerText) || "").trim().toLowerCase();
                if (txt && (txt.includes(targetName) || (firstToken.length >= 4 && txt.includes(firstToken)))) {{
                    const clickTarget = item.querySelector('a.msg-conversation-listitem__link, .msg-conversation-card__content--selectable') || item;
                    clickTarget.click();
                    return "clicked_matching_thread";
                }}
            }}

            // If activeTitle is loaded and belongs to a DIFFERENT person (e.g. LinkedIn defaulted to top inbox message) and we have the person's profile URL, redirect to their profile so we never show the wrong person
            if (activeTitle && !activeTitle.includes(firstToken) && profileFallback && profileFallback.includes("linkedin.com/in/")) {{
                if (window.__aaLiCheckedWrongCount === undefined) {{
                    window.__aaLiCheckedWrongCount = 1;
                    return "waiting_for_search_filter";
                }}
                window.location.href = profileFallback;
                return "redirected_to_profile";
            }}
            return "waiting";
        }})()
        """

        for attempt in range(10):
            time.sleep(0.8 if attempt > 0 else 1.1)
            try:
                tabs = self._get_live_cdp_tabs(port)
                target_tab = None
                if tab_id:
                    target_tab = next((t for t in tabs if str(t.get("id") or "") == tab_id), None)
                if not target_tab:
                    target_tab = next(
                        (
                            t
                            for t in tabs
                            if str(t.get("type") or "") == "page" and "linkedin.com" in str(t.get("url") or "").lower()
                        ),
                        None,
                    )
                if not target_tab or not target_tab.get("webSocketDebuggerUrl"):
                    continue
                ws_url = str(target_tab["webSocketDebuggerUrl"])

                async def _eval_li() -> str:
                    import websockets

                    async with websockets.connect(ws_url, open_timeout=1.5, close_timeout=0.8) as ws:
                        await ws.send(
                            json.dumps(
                                {
                                    "id": 1,
                                    "method": "Runtime.evaluate",
                                    "params": {"expression": js_verify_or_select_linkedin, "returnByValue": True},
                                }
                            )
                        )
                        raw_msg = json.loads(await asyncio.wait_for(ws.recv(), timeout=2.5))
                        return str(raw_msg.get("result", {}).get("result", {}).get("value") or "")

                status = asyncio.run(_eval_li())
                if status in ("not_messaging_page", "matched_active_thread", "clicked_matching_thread", "redirected_to_profile"):
                    return
            except Exception:
                continue

    def _apply_dock_tile_via_cdp(self, port: int) -> None:
        import base64
        import time

        res_dir = self._find_bundled_resources_dir()
        repo_res_dir = Path(__file__).resolve().parents[2] / "packaging" / "assets"
        png_candidates: list[Path] = []
        if res_dir:
            png_candidates.append(res_dir / "BrowserIcon.png")
        png_candidates.extend([
            Path("/Applications/AutoApply.app/Contents/Resources/BrowserIcon.png"),
            repo_res_dir / "BrowserIcon.png",
            Path(__file__).resolve().parents[2] / "packaging" / "extensions" / "autoapply_companion" / "icon-128.png",
        ])
        icon_png = next((p for p in png_candidates if p.is_file()), None)
        b64_img = base64.b64encode(icon_png.read_bytes()).decode("ascii") if icon_png else ""

        for _ in range(10):
            try:
                with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/version", timeout=0.8) as resp:
                    ver = json.loads(resp.read().decode("utf-8"))
                    ws_url = str(ver.get("webSocketDebuggerUrl", ""))
                if ws_url:
                    from websockets.sync.client import connect as ws_connect

                    with ws_connect(ws_url, open_timeout=1.5, close_timeout=0.8) as bws:
                        if b64_img:
                            bws.send(
                                json.dumps(
                                    {
                                        "id": 77,
                                        "method": "Browser.setDockTile",
                                        "params": {"image": b64_img},
                                    }
                                )
                            )
                            bws.recv()
                        bws.send(
                            json.dumps(
                                {
                                    "id": 78,
                                    "method": "Target.createTarget",
                                    "params": {"url": "chrome://extensions", "background": True},
                                }
                            )
                        )
                        create_msg = json.loads(bws.recv())
                        ext_tid = str(create_msg.get("result", {}).get("targetId", ""))

                    if ext_tid:
                        time.sleep(0.18)
                        targets = self._get_live_cdp_tabs(port)
                        ext_tab = next((t for t in targets if t.get("id") == ext_tid and t.get("webSocketDebuggerUrl")), None)
                        if ext_tab:
                            js_enable_and_pin = f"""
                            (async () => {{
                                try {{
                                    await chrome.developerPrivate.updateProfileConfiguration({{inDeveloperMode: true}});
                                    for (const id of [{json.dumps(AUTOAPPLY_COMPANION_EXTENSION_ID)}, {json.dumps(CAPSOLVER_EXTENSION_ID)}]) {{
                                        try {{ await chrome.management.setEnabled(id, true); }} catch (_) {{}}
                                        try {{ await chrome.developerPrivate.updateExtensionConfiguration({{extensionId: id, pinnedToToolbar: true}}); }} catch (_) {{}}
                                    }}
                                }} catch (_) {{}}
                                return true;
                            }})()
                            """
                            with ws_connect(str(ext_tab["webSocketDebuggerUrl"]), open_timeout=1.5, close_timeout=0.8) as ews:
                                ews.send(
                                    json.dumps(
                                        {
                                            "id": 79,
                                            "method": "Runtime.evaluate",
                                            "params": {
                                                "expression": js_enable_and_pin,
                                                "awaitPromise": True,
                                                "returnByValue": True,
                                            },
                                        }
                                    )
                                )
                                ews.recv()
                        with ws_connect(ws_url, open_timeout=1.5, close_timeout=0.8) as bws:
                            bws.send(
                                json.dumps(
                                    {
                                        "id": 80,
                                        "method": "Target.closeTarget",
                                        "params": {"targetId": ext_tid},
                                    }
                                )
                            )
                            bws.recv()
                    return
            except Exception:
                time.sleep(0.35)

    def _autofill_active_cloakbrowser_tab(self, job: dict[str, Any]) -> int:
        port = PARTITION_CDP_PORTS["ats_ephemeral"]
        tabs = self._get_live_cdp_tabs(port)
        first_tab = next((t for t in tabs if t.get("webSocketDebuggerUrl")), None)
        ws_url = str((first_tab or {}).get("webSocketDebuggerUrl") or "")
        if not ws_url:
            self._launch_isolated_browser(
                target="job_ats",
                job_id=job["job_id"],
                custom_url=job["canonical_url"],
                raw_state=self._load_raw_state(),
                dry_run=False,
            )
            return len(job.get("screening_answers", {}))

        raw = self._load_raw_state()
        hdr = raw.get("knowledge_base", {}).get("profile_header", {})
        prefs = raw.get("onboarding", {}).get("preferences", {})
        facts = {
            f["key"]: str(f["value"])
            for f in self._list_facts()
            if f["confirmed"] and not f["superseded_by_id"]
        }
        full_name = hdr.get("full_name") or facts.get("full_name", "")
        email = hdr.get("email") or facts.get("contact_email", "")
        phone = hdr.get("phone") or facts.get("contact_phone", "")
        linkedin = hdr.get("linkedin_url") or facts.get("linkedin_url", "")
        use_highest = bool(prefs.get("use_highest_listed_range", True))
        job_max = int(job.get("salary_max_usd", 0))
        cur = str(prefs.get("salary_currency", "USD"))
        if use_highest and job_max > 0:
            salary_str = f"{cur} {job_max:,}"
        else:
            salary_str = f"{cur} {int(prefs.get('minimum_salary_usd', 150000)):,} - {int(prefs.get('target_salary_usd', 200000)):,}"

        js_payload = json.dumps(
            {
                "name": full_name,
                "email": email,
                "phone": phone,
                "linkedin": linkedin,
                "salary": salary_str,
            }
        )
        js_expr = f"""
        (async () => {{
            const data = {js_payload};
            const humanTypingCadenceMs = () => 85 + Math.floor(Math.random() * 61);
            const typeHuman = async (el, val) => {{
                el.focus();
                const proto = el.tagName.toLowerCase() === 'textarea' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
                const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
                let cur = '';
                for (const ch of Array.from(String(val))) {{
                    cur += ch;
                    el.dispatchEvent(new KeyboardEvent('keydown', {{ key: ch, bubbles: true }}));
                    if (setter) setter.call(el, cur); else el.value = cur;
                    el.dispatchEvent(new Event('input', {{ bubbles: true }}));
                    el.dispatchEvent(new KeyboardEvent('keyup', {{ key: ch, bubbles: true }}));
                    await new Promise((r) => setTimeout(r, humanTypingCadenceMs()));
                }}
                el.dispatchEvent(new Event('change', {{ bubbles: true }}));
                el.style.outline = '2px solid #10b981';
            }};
            let count = 0;
            for (const el of document.querySelectorAll('input, textarea')) {{
                const hint = ((el.name || '') + ' ' + (el.id || '') + ' ' + (el.placeholder || '') + ' ' + (el.getAttribute('aria-label') || '')).toLowerCase();
                if (data.name && (hint.includes('name') && !hint.includes('company'))) {{
                    await typeHuman(el, data.name); count++;
                }} else if (data.email && hint.includes('email')) {{
                    await typeHuman(el, data.email); count++;
                }} else if (data.phone && (hint.includes('phone') || hint.includes('tel'))) {{
                    await typeHuman(el, data.phone); count++;
                }} else if (data.linkedin && hint.includes('linkedin')) {{
                    await typeHuman(el, data.linkedin); count++;
                }} else if (data.salary && (hint.includes('salary') || hint.includes('compensation') || hint.includes('pay'))) {{
                    await typeHuman(el, data.salary); count++;
                }}
            }}
            return count;
        }})()
        """

        async def _eval() -> int:
            import websockets

            live_ws = await _cdp_probe_or_recover_target_async(port, first_tab or {"webSocketDebuggerUrl": ws_url})
            async with websockets.connect(live_ws or ws_url, open_timeout=1.5, close_timeout=1.0) as ws:
                req_id = 1

                async def _send_cmd(method: str, params: dict[str, Any] | None = None, timeout_s: float = 120.0) -> dict[str, Any]:
                    nonlocal req_id
                    cid = req_id
                    req_id += 1
                    await ws.send(json.dumps({"id": cid, "method": method, "params": params or {}}))
                    while True:
                        raw_msg = await asyncio.wait_for(ws.recv(), timeout=timeout_s)
                        resp_obj = json.loads(raw_msg)
                        if resp_obj.get("method") == "Page.javascriptDialogOpening":
                            d_params = resp_obj.get("params") or {}
                            accept_flag, prompt_txt = _decide_js_dialog_action(
                                str(d_params.get("type") or "alert"),
                                str(d_params.get("message") or ""),
                                allow_submit=False,
                                default_prompt=str(d_params.get("defaultPrompt") or ""),
                            )
                            h_params: dict[str, Any] = {"accept": accept_flag}
                            if prompt_txt is not None:
                                h_params["promptText"] = prompt_txt
                            req_id += 1
                            await ws.send(
                                json.dumps(
                                    {
                                        "id": req_id,
                                        "method": "Page.handleJavaScriptDialog",
                                        "params": h_params,
                                    }
                                )
                            )
                            continue
                        if resp_obj.get("id") == cid:
                            return resp_obj

                await _cdp_enable_dialog_guard_on_ws(_send_cmd, mode="prefill", duration_ms=45000)
                resp = await _send_cmd(
                    "Runtime.evaluate",
                    {"expression": js_expr, "awaitPromise": True, "returnByValue": True},
                    timeout_s=120.0,
                )
                return int(resp.get("result", {}).get("result", {}).get("value", 0))

        try:
            return asyncio.run(_eval())
        except Exception:
            return 0

    @staticmethod
    def _clean_job_title_and_company(title: str, company: str) -> tuple[str, str]:
        """Strip board noise like '(Verified job)' and drop company names or wrapper headers that are not real role titles."""
        noise = re.compile(r"\s*[\(\[]\s*(verified job|verified|promoted|easy apply|actively hiring|new)\s*[\)\]]\s*", re.IGNORECASE)
        clean_title = re.sub(r"\s+", " ", noise.sub(" ", str(title or ""))).strip(" -|·")
        clean_company = re.sub(r"\s+", " ", noise.sub(" ", str(company or ""))).strip(" -|·")
        # If title is 'Work at Trulioo' or 'Careers at Company', extract company if missing and clear generic wrapper title
        m_wrapper = re.match(
            r"^(?:work|careers?|jobs?|openings?|opportunities|join\s+us|work\s+with\s+us)\s+(?:at|with|@)\s+(.+)$",
            clean_title,
            flags=re.IGNORECASE,
        )
        if m_wrapper:
            if not clean_company or clean_company.lower() in ("target employer", "employer", "company"):
                clean_company = m_wrapper.group(1).strip(" -|·")
            clean_title = ""
        bad_titles = {
            "",
            "work",
            "careers",
            "career",
            "jobs",
            "job",
            "openings",
            "current openings",
            "open positions",
            "search career opportunities",
            "career opportunities",
            "job opportunities",
            "join us",
            "join our team",
            "work with us",
            "apply",
            "application",
            "dawn",
            "sign in",
            "signin",
            "log in",
            "login",
            "register",
            "returning users",
            "welcome, there",
            "complete your application",
        }
        if clean_title.lower() in bad_titles or re.search(
            r"(available only in|not available in|sorry for the inconvenience|access denied|page not found|404|403|forbidden|no longer accepting|no longer available|job has expired|position has been filled|security check|verify you are human)",
            clean_title,
            flags=re.IGNORECASE,
        ):
            clean_title = ""
        bad_companies = {"", "employer", "featured employer", "target employer", "target company", "company", "linkedin", "hiring team", "unknown", "n/a"}
        low_c = clean_company.lower()
        low_t = clean_title.lower()
        if low_c in bad_companies or (low_c and (low_c == low_t or (low_t and low_c in low_t and len(low_c) > 12))):
            clean_company = ""
        return clean_title, clean_company

    def _build_job_entry(
        self,
        *,
        url: str,
        company: str,
        title: str,
        workplace: str,
        country: str,
        salary: int,
        raw: dict[str, Any],
        description: str = "",
    ) -> dict[str, Any]:
        short_id = uuid.uuid4().hex[:6]
        title, company = self._clean_job_title_and_company(title, company)
        hdr = raw.get("knowledge_base", {}).get("profile_header", {})
        prefs = raw.get("onboarding", {}).get("preferences", {})
        facts = {
            f["key"]: str(f["value"])
            for f in self._list_facts()
            if f["confirmed"] and not f["superseded_by_id"]
        }
        use_highest = bool(prefs.get("use_highest_listed_range", True))
        cur = str(prefs.get("salary_currency", "USD"))
        if use_highest and salary > 0:
            comp_answer = f"{cur} {salary:,}"
        else:
            comp_answer = (
                f"{cur} {int(prefs.get('minimum_salary_usd', 150000)):,} – "
                f"{cur} {int(prefs.get('target_salary_usd', 200000)):,}"
            )
        raw_full_name = str(hdr.get("full_name") or facts.get("full_name") or "Alex Mercer").strip()
        if "Alexander" in raw_full_name:
            raw_full_name = raw_full_name.replace("Alexander", "Alex")
        clean_full_name = re.sub(r"^(?:Mr\.|Ms\.|Mrs\.|Dr\.|Mx\.)\s*", "", raw_full_name, flags=re.IGNORECASE).strip() or "Alex Mercer"
        posted_at = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        return {
            "job_id": f"job_{short_id}",
            "application_id": f"app_{short_id}",
            "company_name": company,
            "direct_employer_id": f"emp_{re.sub(r'[^a-z0-9]', '', company.lower())[:12] or short_id}",
            "title": title,
            "canonical_url": url,
            "description": description,
            "posted_at": posted_at,
            "posted_label": self._format_job_posted_label(posted_at),
            "workplace_mode": workplace if workplace in ("remote", "hybrid", "onsite") else "remote",
            "location_label": f"{workplace.capitalize()} ({country})",
            "eligible_countries": [country],
            "sponsorship_offered": True,
            "is_open": True,
            "salary_max_usd": salary,
            "eligible": True,
            "exclusion_reason": None,
            "filter_summary": "Matches Criteria",
            "dedupe_status": "clear_30d_window",
            "state": "ready_to_submit",
            "tracker_sync_state": "pending",
            "remote_receipt_id": None,
            "uncertain_effect": False,
            "approved_artifact_sha256": raw["documents"][0]["pdf_sha256"] if raw["documents"] else "",
            "screening_answers": {
                "Full Name": clean_full_name,
                "Email": hdr.get("email") or facts.get("contact_email", raw["onboarding"]["gmail_config"]["account_email"] or "Not set"),
                "Phone": hdr.get("phone") or facts.get("contact_phone", "Not set"),
                "LinkedIn": str(hdr.get("linkedin_url") or facts.get("linkedin_url") or "https://linkedin.com/in/alexander-mercer").strip(),
                "Website": str(hdr.get("portfolio_url") or "https://www.turboapply.ca").strip(),
                "Current Company": "Apex Industrial",
                "Years of PM Experience": "6",
                "Technical Degree": "Yes",
                "Desired Compensation": comp_answer,
            },
            "timeline": [
                f"Added {title} at {company} ({url})" if company else f"Added {title} ({url})",
            ],
        }

