    def _audit_verified_board_sessions(self, raw: dict[str, Any]) -> set[str]:
        """Inspect real browser session cookies and saved credentials to determine which auth-gated boards are truly authenticated."""
        verified: set[str] = set()
        onb = raw.get("onboarding", {})
        if bool(onb.get("linkedin_config", {}).get("session_connected", False)):
            verified.add("linkedin")

        cookie_db = self.root / "browser-profiles" / "extension_automation" / "Default" / "Cookies"
        if cookie_db.is_file():
            try:
                conn = sqlite3.connect(f"file:{cookie_db}?mode=ro", uri=True, timeout=1.0)
                rows = conn.execute("SELECT host_key, name FROM cookies").fetchall()
                conn.close()
                for hk, cname in rows:
                    host_l = str(hk or "").lower()
                    name_l = str(cname or "").lower()
                    if "linkedin.com" in host_l and name_l in ("li_at", "liap"):
                        verified.add("linkedin")
                    elif "hh.ru" in host_l and name_l in ("hhtoken", "crypted_hhuid"):
                        verified.add("hh")
                    elif "wellfound.com" in host_l and name_l in ("_wellfound_session", "user_id", "remember_user_token"):
                        verified.add("wellfound")
                    elif "welcometothejungle.com" in host_l and ("session" in name_l or "token" in name_l) and name_l != "gb_session_id":
                        verified.add("welcometothejungle")
                    elif "theladders.com" in host_l and ("session" in name_l or "token" in name_l or "auth" in name_l):
                        verified.add("theladders")
                    elif "workable.com" in host_l and name_l in ("koa.sess", "_grant_resume"):
                        verified.add("workable")
            except Exception:
                pass

        vault_path = self.root / "credential_vault.json"
        if vault_path.is_file():
            try:
                v_raw = json.loads(vault_path.read_text(encoding="utf-8"))
                creds = v_raw if isinstance(v_raw, list) else v_raw.get("credentials", [])
                for c in creds:
                    if not isinstance(c, dict):
                        continue
                    dom = str(c.get("domain") or c.get("service_name") or "").lower()
                    for item in self._get_default_job_boards_catalog():
                        if item["domain"].lower() in dom or item["id"].lower() in dom:
                            verified.add(str(item["id"]).lower())
            except Exception:
                pass
        return verified

    def _build_job_boards_state(self, raw: dict[str, Any]) -> list[dict[str, Any]]:
        onb = raw.get("onboarding", {})
        jb_cfg = onb.get("job_boards_config", {})
        explicit_states = jb_cfg.get("states", {}) if isinstance(jb_cfg.get("states"), dict) else {}
        user_verified_ids = set(str(x).lower() for x in jb_cfg.get("user_verified_ids", []))
        excluded_ids = set(str(x).lower() for x in jb_cfg.get("excluded_ids", []))
        verified_sessions = self._audit_verified_board_sessions(raw)
        has_live_cookie_db = (self.root / "browser-profiles" / "extension_automation" / "Default" / "Cookies").is_file()

        # Clean up any legacy unverified state (e.g. wellfound marked true without session or explicit user verification)
        if has_live_cookie_db and isinstance(explicit_states, dict):
            for k in list(explicit_states.keys()):
                k_low = str(k).lower()
                if explicit_states.get(k) is True and k_low not in user_verified_ids and k_low not in verified_sessions and k_low not in ("linkedin", "hh", "greenhouse", "lever", "ashby"):
                    del explicit_states[k]

        result: list[dict[str, Any]] = []
        for item in self._get_default_job_boards_catalog():
            bid = str(item["id"]).lower()
            is_excluded = bid in excluded_ids
            if is_excluded:
                is_operational = False
            elif bid in explicit_states and (bid in user_verified_ids or bid in verified_sessions or not has_live_cookie_db or explicit_states[bid] is False):
                is_operational = bool(explicit_states[bid])
            elif bid in verified_sessions:
                is_operational = True
            else:
                is_operational = bool(item["default_operational"])

            result.append(
                {
                    "id": bid,
                    "name": item["name"],
                    "slug": item["slug"],
                    "domain": item["domain"],
                    "url": item["url"],
                    "auth_url": item["auth_url"],
                    "is_primary": bool(item["is_primary"]),
                    "requires_auth": bool(item["requires_auth"]),
                    "operational": is_operational,
                    "excluded": is_excluded,
                    "operational_note": item["operational_note"],
                    "attention_reason": item["attention_reason"],
                }
            )
        return result

    def _reevaluate_all_jobs(self, raw: dict[str, Any]) -> None:
        p = raw["onboarding"]["preferences"]
        res_country = str(p.get("residence_country") or "").strip().upper()
        if not res_country:
            hdr_loc = str(raw.get("knowledge_base", {}).get("profile_header", {}).get("location") or "").strip().lower()
            if "georgia" in hdr_loc or "batumi" in hdr_loc or "tbilisi" in hdr_loc:
                res_country = "GE"
            elif "canada" in hdr_loc or "vancouver" in hdr_loc or "toronto" in hdr_loc:
                res_country = "CA"
            else:
                res_country = next(
                    (str(k).upper() for k, v in p.get("authorized_countries", {}).items() if v),
                    "GE" if bool(p.get("global_b2b_contractor", False)) else "US",
                )
        auth_map = {str(k).upper(): bool(v) for k, v in p.get("authorized_countries", {}).items()}
        spons_map = {
            str(k).upper(): bool(v) for k, v in p.get("requires_sponsorship_by_country", {}).items()
        }
        w_reg = p.get("work_auth_by_region", {}) if isinstance(p.get("work_auth_by_region"), dict) else {}
        if res_country == "GE":
            auth_map["GE"] = True
            spons_map["GE"] = False
        for reg_code, reg_val in w_reg.items():
            rc = str(reg_code).upper()
            rv = str(reg_val or "").strip()
            if rv in ("Citizen", "Citizen / PR", "PR", "PR (Green Card)") and rc not in p.get("authorized_countries", {}):
                auth_map[rc] = True
                spons_map[rc] = False

        cand_prefs = CandidateJobPreferences(
            residence_country=res_country,
            authorized_countries=auth_map,
            requires_sponsorship_by_country=spons_map,
            accepted_workplace_modes=set(p["accepted_workplace_modes"]),
            minimum_salary_usd=int(p["minimum_salary_usd"]),
            excluded_employers=set(p["excluded_employers"]),
        )
        excluded_kw = [k.lower() for k in p.get("excluded_keywords", []) if k.strip()]
        excluded_co = [c.lower() for c in p.get("excluded_employers", []) if c.strip()]
        jb_cfg = raw.get("onboarding", {}).get("job_boards_config", {})
        excluded_board_ids = set(str(x).lower() for x in jb_cfg.get("excluded_ids", []))
        excluded_board_domains = [
            b["domain"].lower()
            for b in self._get_default_job_boards_catalog()
            if b["id"] in excluded_board_ids and b.get("domain")
        ]
        is_global_b2b = bool(p.get("global_b2b_contractor", False))

        for j in raw["jobs"]:
            if j.get("eligibility_manual_override"):
                eligible = bool(j.get("eligible", True))
                reason = j.get("exclusion_reason") if not eligible else None
            elif j.get("preflight_ineligible_reason"):
                eligible = False
                reason = str(j.get("preflight_ineligible_reason"))
            else:
                posting = JobPosting(
                    job_id=j["job_id"],
                    direct_employer_id=j["direct_employer_id"],
                    canonical_role_id=j["job_id"],
                    canonical_url=j["canonical_url"],
                    title=j["title"],
                    workplace_mode=j["workplace_mode"],
                    eligible_countries=tuple(j["eligible_countries"]),
                    sponsorship_offered=bool(j["sponsorship_offered"]),
                    is_open=bool(j["is_open"]),
                    salary_max_usd=int(j["salary_max_usd"]),
                )
                res = evaluate_job_eligibility(posting, cand_prefs)
                eligible = res.eligible
                reason = res.exclusion_reason

                if (
                    not eligible
                    and is_global_b2b
                    and str(j.get("workplace_mode") or "").lower() == "remote"
                    and reason in (
                        "country_residence_or_location_ineligible",
                        "work_authorization_or_sponsorship_ineligible",
                    )
                ):
                    elig_c_set = {str(c).upper() for c in (j.get("eligible_countries") or [])}
                    if elig_c_set & {"GE", "GLOBAL", "WW", "ANYWHERE"}:
                        eligible = True
                        reason = None

                # Also check human-friendly excluded company names, excluded keywords, and excluded job boards
                haystack = f"{j.get('title', '')} {j.get('company_name', '')} {j.get('description', '')}".lower()
                url_lower = str(j.get("canonical_url", "")).lower()
                if eligible and any(co in j.get("company_name", "").lower() for co in excluded_co):
                    eligible = False
                    reason = "excluded_employer"
                if eligible and any(kw in haystack for kw in excluded_kw):
                    eligible = False
                    reason = "excluded_keyword"
                if eligible and any(dom in url_lower for dom in excluded_board_domains):
                    eligible = False
                    reason = "excluded_job_board"

            j["eligible"] = eligible
            human_reason = self._humanize_exclusion_reason(reason)
            j["exclusion_reason"] = human_reason
            issue_obj = j.get("application_issue") if isinstance(j.get("application_issue"), dict) else None
            if issue_obj and issue_obj.get("reason"):
                j["filter_summary"] = f"Issue: {issue_obj['reason']}"
            else:
                j["filter_summary"] = "Matches Filters" if eligible else (human_reason or "Not Eligible")
            if not eligible and j["state"] != "submitted_verified":
                j["state"] = "ineligible"
            elif eligible and j["state"] == "ineligible":
                tl_entries = j.get("timeline") if isinstance(j.get("timeline"), list) else []
                has_apply_act = any(
                    any(tok in str(t).lower() for tok in ("prefilled", "autofilled", "prepared tailored"))
                    for t in tl_entries
                )
                j["state"] = "applying" if (j.get("pipeline_stage") == "applying" or has_apply_act) else "ready_to_submit"
        self._normalize_job_tracker_fields(raw)
        self._ensure_all_jobs_scored(raw)

